pub mod parser;
pub mod validators;

pub use parser::{split_path, URL};
pub use validators::{is_host_valid, is_port_valid, is_scheme_valid};

//! URL parsing, re-implemented from observed behavior of the C++ url_parser library.

/// A parsed URL broken into scheme, host, port and path components.
pub struct URL {
    scheme: String,
    host: String,
    port: String,
    path: String,
}

impl URL {
    /// Parse a URL string.
    ///
    /// Parsing order:
    /// 1. Truncate at the first '?' or '#' (query/fragment are discarded).
    /// 2. Split at the first "://" into scheme and the remainder.
    /// 3. If a scheme separator was present, split the remainder at the
    ///    first '/' into authority and path; otherwise the whole remainder
    ///    is the path.
    /// 4. Strip userinfo (up to the first '@') from the authority, then
    ///    split host and port at the first ':'.
    pub fn new(url: &str) -> URL {
        // 1. Drop query/fragment.
        let main = match url.find(|c| c == '?' || c == '#') {
            Some(i) => &url[..i],
            None => url,
        };

        // 2. Scheme separator.
        let (scheme, rest, has_scheme) = match main.find("://") {
            Some(i) => (&main[..i], &main[i + 3..], true),
            None => ("", main, false),
        };

        // 3. Authority vs. path.
        let (authority, path) = if has_scheme {
            match rest.find('/') {
                Some(i) => (&rest[..i], &rest[i..]),
                None => (rest, ""),
            }
        } else {
            ("", rest)
        };

        // 4. Userinfo, then host:port.
        let after_userinfo = match authority.find('@') {
            Some(i) => &authority[i + 1..],
            None => authority,
        };
        let (host, port) = match after_userinfo.find(':') {
            Some(i) => (&after_userinfo[..i], &after_userinfo[i + 1..]),
            None => (after_userinfo, ""),
        };

        URL {
            scheme: scheme.to_string(),
            host: host.to_string(),
            port: port.to_string(),
            path: path.to_string(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> &str {
        &self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    /// A URL is valid when parsing yields a non-empty host or path.
    pub fn is_valid_url(url: &str) -> bool {
        let parsed = URL::new(url);
        !parsed.host.is_empty() || !parsed.path.is_empty()
    }
}

/// Split a path into its segments: split on '/', skipping empty segments.
pub fn split_path(path: &str) -> Vec<String> {
    path.split('/')
        .filter(|seg| !seg.is_empty())
        .map(|seg| seg.to_string())
        .collect()
}

//! Component validators, re-implemented from observed C++ behavior.

/// C-locale ASCII checks (the C++ side uses ::isalpha / ::isalnum).
fn is_alpha(b: u8) -> bool {
    b.is_ascii_alphabetic()
}

fn is_alnum(b: u8) -> bool {
    b.is_ascii_alphanumeric()
}

/// Scheme: ^[A-Za-z][A-Za-z0-9+.-]*$
pub fn is_scheme_valid(scheme: &str) -> bool {
    let bytes = scheme.as_bytes();
    if bytes.is_empty() || !is_alpha(bytes[0]) {
        return false;
    }
    bytes[1..]
        .iter()
        .all(|&b| is_alnum(b) || b == b'+' || b == b'-' || b == b'.')
}

/// Host: non-empty, every character in [A-Za-z0-9.\-\[\]].
pub fn is_host_valid(host: &str) -> bool {
    !host.is_empty()
        && host
            .bytes()
            .all(|b| is_alnum(b) || b == b'-' || b == b'.' || b == b'[' || b == b']')
}

/// Port: parsed with std::stoi semantics — leading C-locale whitespace is
/// skipped, an optional sign is allowed, at least one digit must follow,
/// and trailing garbage is ignored. Overflow of a C int is invalid.
/// The parsed value must lie in [0, 65535].
pub fn is_port_valid(port: &str) -> bool {
    let bytes = port.as_bytes();
    let mut i = 0;

    // std::stoi skips leading whitespace (C locale).
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }

    // Optional sign.
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    // At least one digit is required.
    if i >= bytes.len() || !bytes[i].is_ascii_digit() {
        return false;
    }

    // Accumulate with saturation: any value whose magnitude overflows a
    // C int (or the port range) is invalid anyway.
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        if value > i32::MAX as i64 {
            value = i32::MAX as i64 + 1; // out of std::stoi's int range
            break;
        }
        i += 1;
    }

    if negative {
        value = -value;
    }

    (0..=65535).contains(&value)
}

mod url_parser;

use url_parser::{is_host_valid, is_port_valid, is_scheme_valid, split_path, URL};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let url = &args[1];

    println!("{}", URL::is_valid_url(url) as i32);

    let parser = URL::new(url);

    println!("{}", is_scheme_valid(parser.scheme()) as i32);
    println!("{}", is_host_valid(parser.host()) as i32);
    println!("{}", is_port_valid(parser.port()) as i32);

    let path_segments = split_path(parser.path());
    println!("{}", path_segments.len());

    for segment in &path_segments {
        println!("{}", segment);
    }
}
